"use client";

import { motion } from "framer-motion";
import { useState } from "react";

const pools = [
  {
    pair: "SOL / USDC",
    volume: "$14.2M",
    yield: "+8.4% APY",
  },
  {
    pair: "JUP / SOL",
    volume: "$8.7M",
    yield: "+14.2% APY",
  },
  {
    pair: "BONK / SOL",
    volume: "$24.1M",
    yield: "+29.5% APY",
  },
  {
    pair: "RAY / USDC",
    volume: "$6.8M",
    yield: "+11.8% APY",
  },
];

const label = {
  pair: "Pool",
  volume: "24h Vol",
  yield: "Yield",
};

const CARD_HEIGHT = 70;
const GAP = 8;

export default function RunStatsStacks() {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <div className="flex h-[600px] w-full flex-col items-center justify-center overflow-hidden">
      <div
        className="relative flex h-full w-full flex-col items-center justify-center"
        style={{
          perspective: "1000px",
        }}
      >
        {pools.map((pool, i) => {
          return (
            <motion.div
              className="absolute w-[250px] rounded-3xl border-t border-neutral-50 bg-neutral-200 bg-opacity-80 px-3 py-3 backdrop-blur-2xl dark:border-neutral-50/20 dark:bg-neutral-800"
              key={i}
              animate={isOpen ? "open" : "closed"}
              style={{
                height: CARD_HEIGHT,
              }}
              variants={{
                open: {
                  y: i * (CARD_HEIGHT + GAP),
                  z: 0,
                  top: `16%`,
                },
                closed: {
                  y: i * 10,
                  z: i * 40,
                  top: `50%`,
                },
              }}
              transition={{
                type: "spring",
                stiffness: 200,
                damping: 30,
              }}
              onClick={() => {
                setIsOpen(!isOpen);
              }}
            >
              <div className="flex justify-between text-[15px]">
                {Object.keys(label).map((key) => {
                  return (
                    <div
                      className="pointer-events-none flex flex-col"
                      key={key}
                    >
                      <span className="text-neutral-950/50 dark:text-neutral-50/50">
                        {label[key as keyof typeof label]}
                      </span>
                      <span className="text-neutral-950 dark:text-neutral-50 font-medium">
                        {pool[key as keyof typeof pool]}
                      </span>
                    </div>
                  );
                })}
              </div>
            </motion.div>
          );
        })}
      </div>
    </div>
  );
}
